Forward refs, they allow you to pass reference to component. This component use that reference to access DOM element. Good for components that need access to DOM element, like event handlers. Example:

import React, { useRef, forwardRef } from 'react';

const MyComponent = forwardRef((props, ref) => {
  const inputRef = useRef(null);

  const handleInput = (event) => {
    console.log(event.target.value);
  };

  return (
    <input ref={inputRef} onChange={handleInput} />
  );
});

const App = () => {
  const inputRef = useRef(null);

  return (
    <div>
      <MyComponent ref={inputRef} />
      <button onClick={() => inputRef.current.focus()}>Focus input</button>
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById('root'));

