Forward refs, they allow you to pass reference to component. This component can use that reference to access DOM element. This useful for components that need to manipulate DOM, like buttons or inputs. You use forwardRef() function to create forward ref. Then, you pass that ref to component you want to use it. Example:

import React, { forwardRef } from 'react';

const MyComponent = forwardRef((props, ref) => {
  return <input ref={ref} />;
});

const MyComponentWithRef = forwardRef((props, ref) => {
  return <MyComponent ref={ref} />;
});

const App = () => {
  const inputRef = React.useRef(null);

  return (
    <div>
      <MyComponentWithRef ref={inputRef} />
      <button onClick={() => inputRef.current.focus()}>Focus input</button>
    </div>
  );
};

ReactDOM.render(<App />, document.getElementById('root'));

